// Package rust_integration compiles the code generated by the Rust backend together with Rust tests
// that exercise it, and runs them.
//
// The tests use the rustc found in PATH (rustup's proxies work). If there is none, they are skipped.
package rust_integration

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/cristiandonosoc/gochart/internal/files"
	rust_gen "github.com/cristiandonosoc/gochart/internal/generation/rust"
	"github.com/cristiandonosoc/gochart/internal/test_support"
	"github.com/cristiandonosoc/gochart/pkg/backend/common"
	"github.com/cristiandonosoc/gochart/pkg/frontend/gochart_lang"
	"github.com/cristiandonosoc/gochart/pkg/ir"

	"github.com/stretchr/testify/require"
)

// Each case is testdata/<case>/<case>.gochart, tested by testdata/<case>/<case>_test.rs.
var kCases = []string{
	"allocations",
	"data",
	"default_active",
	"delegate_defaults",
	"dispatch",
	"parallel",
	"routes",
}

func TestRustBackend(t *testing.T) {
	rustc, err := exec.LookPath("rustc")
	if err != nil {
		t.Skip("rustc not found in PATH, skipping the Rust backend integration tests")
	}

	gf, err := gochart_lang.NewGochartLangFrontend()
	require.NoError(t, err)

	for _, name := range kCases {
		t.Run(name, func(t *testing.T) {
			dir, err := os.MkdirTemp(test_support.TestTmpBase(), name)
			require.NoError(t, err)
			defer os.RemoveAll(dir)

			// Generate the chart next to the test, which includes it with #[path].
			chartPath, err := test_support.RunfilePath(fmt.Sprintf("testdata/%s/%s.gochart", name, name))
			require.NoError(t, err)
			lf, err := files.LoadFileFromPath(chartPath)
			require.NoError(t, err)
			gcdata, err := gf.Process(lf)
			require.NoError(t, err)
			gc, err := ir.ProcessGochartData(gcdata)
			require.NoError(t, err)
			content, err := rust_gen.GenerateContent(gc, &common.Metadata{Version: "test"})
			require.NoError(t, err)
			require.NoError(t, os.WriteFile(filepath.Join(dir, name+".gochart.rs"), []byte(content), 0644))

			testPath, err := test_support.RunfilePath(fmt.Sprintf("testdata/%s/%s_test.rs", name, name))
			require.NoError(t, err)
			testSource, err := os.ReadFile(testPath)
			require.NoError(t, err)
			crateRoot := filepath.Join(dir, name+"_test.rs")
			require.NoError(t, os.WriteFile(crateRoot, testSource, 0644))

			// Warnings are errors, so the generated code stays warning free.
			binary := filepath.Join(dir, name+"_test")
			if runtime.GOOS == "windows" {
				binary += ".exe"
			}
			compile := exec.Command(rustc, "--edition=2021", "--test", "-D", "warnings", "-o", binary, crateRoot)
			compile.Dir = dir
			if output, err := compile.CombinedOutput(); err != nil {
				t.Fatalf("compiling %s: %v\n%s", name, err, output)
			}

			run := exec.Command(binary)
			run.Dir = dir
			output, err := run.CombinedOutput()
			if err != nil {
				t.Fatalf("running %s: %v\n%s", name, err, output)
			}
			t.Logf("%s", output)
		})
	}
}
